import subprocess, json, os, shutil
def locomo_for(code_lines, complexity_per_line=0, extra=[]):
    # make go file: each line is code, complexity keywords "if"
    d="/tmp/locomo_test"
    shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    with open(os.path.join(d,"a.go"),"w") as f:
        for i in range(code_lines):
            if complexity_per_line:
                # add that many "if " ?
                f.write("x := 1 "+" ".join(["if true {}"]*complexity_per_line)+"\n") # might count?
            else:
                f.write("x := 1\n")
    r=subprocess.run(["./executable","--locomo","-f","json2"]+extra+[d],capture_output=True,text=True)
    j=json.loads(r.stdout)
    s=j["languageSummary"][0] if j["languageSummary"] else {}
