def make(code, comp):
    d="/tmp/locomo_test2"
    shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    with open(os.path.join(d,"a.go"),"w") as f:
        for i in range(comp):
            f.write("if true {}\n")
        for i in range(code-comp):
            f.write("x := 1\n")
    r=subprocess.run(["./executable","--locomo","-f","json2",d],capture_output=True,text=True)
