    print(f"code={s['Code']} comp={s['Complexity']} cycles={j['estimatedLLMCycles']} mult={j['estimatedLLMAverageComplexityMultiplier']} in={j['estimatedLLMInputTokens']} out={j['estimatedLLMOutputTokens']}")
for code,comp in [(100,0),(100,10),(100,50),(100,100),(1000,0),(1000,500),(10,0),(10,10),(11,2)]:
    make(code,comp)
