{"command":"python3 << 'PY' > /tmp/probe_ext.txt 2>&1
import subprocess, json, os, shutil, collections
langs=[]
with open("/tmp/langs.txt") as f:
    for line in f:
        line=line.strip(); idx=line.rfind("("); name=line[:idx].strip(); exts=line[idx+1:-1].split(",") if line[idx+1:-1] else []
        langs.append((name,exts))

def count_names(names):
    # batch many files in one dir to speed, each file content simple
    d="/tmp/probe_batch"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    for i,n in enumerate(names):
        # avoid path separators
        p=os.path.join(d,n)
        try:
            with open(p,"w") as f: f.write("hello world\n")
        except Exception as e:
            print("err create",n,e)
    r=subprocess.run(["./executable","-f","json","--by-file","--count-ignore",d],capture_output=True,text=True)
    try: j=json.loads(r.stdout)
    except: print("parse err",r.stdout,r.stderr); return {}
    res={}
    for lang in j:
        for fi in lang["Files"]:
            res[fi["Filename"]]=(lang["Name"],fi["Extension"],fi["PossibleLanguages"])
    return res

# Test all distinct ext tokens as filename "file.<ext>" and as "<ext>" and as uppercase etc?
all_exts=[]
seen=set()
for name,exts in langs:
    for e in exts:
        if e not in seen:
            seen.add(e); all_exts.append(e)
print("distinct exts",len(all_exts))
# As file.ext where ext may contain dot already
names=[f"file{i}.{e}" if not e.startswith(".") else f"file{i}{e}" for i,e in enumerate(all_exts)]
# But filename mapping back difficult; instead batch with unique prefix per ext but json Filename gives it
res=count_names(names)
# Map prefix index
for i,e in enumerate(all_exts):
    fn=names[i]
    print(f"EXTTEST {e!r} as {fn!r} -> {res.get(fn)}")
print("=== as bare name ===")
names2=all_exts[:]  # file named exactly ext (for dotted exts this is e.g. blade.php)
res2=count_names(names2)
for e in all_exts:
    print(f"BARE {e!r} -> {res2.get(e)}")
PY
wc -l /tmp/probe_ext.txt; head -n 100 /tmp/probe_ext.txt"}

