import json,ast
alltests={}
for fn in ["/tmp/lang_comments.json","/tmp/lang_comments2.json"]:
    for e in json.load(open(fn)):
        d=alltests.setdefault(e["language"],[])
        d.extend(e["tests"])
# result tuple indices: Name, Lines, Code, Comment, Blank, Cx
features={}
for lang,tests in alltests.items():
    # line candidates success proper
    line_ok=[]
    for kind,cand,res in tests:
        if kind=="line" and res and res[2]==1 and res[3]==1:
            if cand not in line_ok: line_ok.append(cand)
    # remove candidates that are start of multi? line /* gave comment2 not included
    # Dedupe: sort by len and keep if no earlier kept is prefix of candidate
    line_sel=[]
    for cand in sorted(set(line_ok),key=lambda x:(len(x),x)):
        if any(cand.startswith(k) for k in line_sel):
            continue
        line_sel.append(cand)
    # multi pairs
    pair_ok=[]
    for kind,cand,res in tests:
        if kind in ("multi","multi_endstart") and res and res[2]==1 and res[3]==3:
            try:
                a,b=cand.split("|",1); pair=(ast.literal_eval(a),ast.literal_eval(b))
            except: continue
            if pair not in pair_ok: pair_ok.append(pair)
    # Make equal start/end quote pairs special: for Python triple is not a real ML pair but docstring; keep note.
    # sort shortest total
    pair_sel=[]
    for pair in sorted(pair_ok,key=lambda p:(len(p[0])+len(p[1]),len(p[0]),p)):
        s,e=pair
        if any(s.startswith(ks) and (e.endswith(ke) or ke in e) for ks,ke in pair_sel):
            continue
        pair_sel.append(pair)
    # If pair is like """ etc and language not Python/Smalltalk (where " is comment in Smalltalk), could be quote not comment: Our test lines start with """ then comment -> for python docstring only that counted comment. For others """ pair test would code3 not selected.
    features[lang]={"line":line_sel,"multi":pair_sel,"line_all":sorted(line_ok),"multi_all":pair_ok}
json.dump(features,open("/tmp/features_comments.json","w"),indent=1)
for lang in sorted(features):
    f=features[lang]
    print(f"{lang}: line={f['line']} multi={f['multi']}")
