#!/usr/bin/env python3
import sys, os, re, math, json, time, datetime, hashlib, struct
from collections import defaultdict

try:
    from constants import HELP_TEXT, LANGUAGES_TEXT, USAGE_TEXT
    from langdata import FEATURES
except Exception:
    from .constants import HELP_TEXT, LANGUAGES_TEXT, USAGE_TEXT
    from .langdata import FEATURES

VERSION = "3.7.0"
START_TIME = time.monotonic()
START_WALL = time.time()

# ---------------- logging ----------------
class Logger:
    verbose = False
    debug = False
    trace = False
    @staticmethod
    def _ts():
        return datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    @classmethod
    def log(cls, level, msg):
        line = f"{level} {cls._ts()}: {msg}\n"
        if level == "ERROR":
            sys.stderr.write(line)
            try: sys.stderr.flush()
            except Exception: pass
        else:
            sys.stdout.write(line)
            try: sys.stdout.flush()
            except Exception: pass
    @classmethod
    def warn(cls, msg):
        if cls.verbose: cls.log("WARN", msg)
    @classmethod
    def debuglog(cls, msg):
        if cls.debug: cls.log("DEBUG", msg)
    @classmethod
    def tracelog(cls, msg):
        if cls.trace: cls.log("TRACE", msg)
    @classmethod
    def error(cls, msg):
        cls.log("ERROR", msg)

# trace timing bookkeeping
TRACE_LANG_BUILT = set()
TRACE_EXT_START = time.perf_counter_ns()

# ---------------- Go-like helpers ----------------
def go_clean(path):
    if path == "":
        return "."
    # Go filepath.Clean (unix)
    rooted = path.startswith("/")
    # split
    parts = path.split("/")
    out = []
    for p in parts:
        if p == "" or p == ".":
            continue
        if p == "..":
            if out and out[-1] != "..":
                out.pop()
            elif not rooted:
                out.append("..")
            continue
        out.append(p)
    res = ("/" if rooted else "") + "/".join(out)
    if res == "":
        return "/" if rooted else "."
    return res

def go_join(*parts):
    # filepath.Join joins with / and Cleans, ignoring empty parts (except if all empty -> "")
    ps = [p for p in parts if p != ""]
    if not ps:
        return ""
    return go_clean("/".join(ps))

def format_int_comma(n):
    # Go humanize.Comma / accounting like used for tabular numbers and money
    try:
        return f"{n:,}"
    except Exception:
        return str(n)

def go_float_str(v):
    # Used mainly inside JSON (python json will handle float). For %.2f style use format_float2.
    return repr(v)

def format_float2(v):
    if isinstance(v, float):
        if math.isnan(v):
            return "NaN"
        if math.isinf(v):
            return "∞" if v > 0 else "-∞"
    return f"{v:.2f}"

def format_float1(v):
    if isinstance(v, float):
        if math.isnan(v):
            return "NaN"
        if math.isinf(v):
            return "∞" if v > 0 else "-∞"
    return f"{v:.1f}"

def go_int_from_float(v):
    # Go conversion float64 -> int64 on amd64: NaN/Inf/out of range -> -9223372036854775808
    try:
        if math.isnan(v) or math.isinf(v):
            return -9223372036854775808
        i = int(v)  # trunc toward zero, python int(float) truncates
        if i > 9223372036854775807 or i < -9223372036854775808:
            return -9223372036854775808
        return i
    except Exception:
        return -9223372036854775808

# bool formatting for debug
def bstr(b):
    return "true" if b else "false"

# Go strconv.ParseInt base 0, bitSize 64
class GoParseError(Exception):
    def __init__(self, kind, msg):
        self.kind = kind  # 'syntax' or 'range'
        self.msg = msg

def parse_go_int(s):
    orig = s
    if s == "":
        raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
    neg = False
    t = s
    if t[0] in "+-":
        neg = t[0] == "-"
        t = t[1:]
        if t == "":
            raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
    # Determine base
    base = 10
    digits = t
    prefix = ""
    low = t.lower()
    if low.startswith("0x"):
        base = 16; digits = t[2:]; prefix = t[:2]
    elif low.startswith("0b"):
        base = 2; digits = t[2:]; prefix = t[:2]
    elif low.startswith("0o"):
        base = 8; digits = t[2:]; prefix = t[:2]
    elif len(t) > 1 and t[0] == "0":
        base = 8; digits = t[1:]; prefix = "0"
    if digits == "":
        raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
