    clean = digits.replace("_", "")
    if clean == "":
        raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
    # validate digits in base
    valid = "0123456789abcdefghijklmnopqrstuvwxyz"[:base] if base <= 36 else ""
    # bases used are 2,8,10,16
    allowed = {2:"01",8:"01234567",10:"0123456789",16:"0123456789abcdefABCDEF"}[base]
    for ch in clean:
        if ch not in allowed:
            raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
    try:
        val = int(clean, base)
    except Exception:
        raise GoParseError("syntax", f'strconv.ParseInt: parsing "{orig}": invalid syntax')
    if neg:
        val = -val
    if val > 9223372036854775807 or val < -9223372036854775808:
        raise GoParseError("range", f'strconv.ParseInt: parsing "{orig}": value out of range')
    return val

def parse_go_float(s):
    orig = s
    if s == "" or s.strip() != s:
        raise GoParseError("syntax", f'strconv.ParseFloat: parsing "{orig}": invalid syntax')
