    double_map = {}
    for name, tokens in LANG_TOKENS:
        for tok in tokens:
            low = tok.lower()
            if low in DOUBLE_EXACT_TOKENS:
                # double extension token: belongs in ext_map and double_map
                if name not in ext_map.setdefault(low, []): ext_map[low].append(name)
                if name not in double_map.setdefault(low, []): double_map[low].append(name)
                continue
            if low in FILENAME_TOKENS:
                if name not in filename_map.setdefault(low, []): filename_map[low].append(name)
                # both tokens also are extensions
                if low in ("dockerfile","makefile","vimrc","gvimrc"):
                    if name not in ext_map.setdefault(low, []): ext_map[low].append(name)
                continue
            # regular extension
            if name not in ext_map.setdefault(low, []): ext_map[low].append(name)
    if count_as_map:
        for src, langs in count_as_map.items():
            ext_map[src] = list(langs)
