    lower = job_name.lower()
    if lower in filename_map:
        return (job_name, list(filename_map[lower]), "filename")
    if lower in double_map:
        return ("", list(double_map[lower]), "double")
    dot_count = job_name.count(".")
    if dot_count == 0 or (dot_count == 1 and job_name.startswith(".")):
        return (job_name, ["#!"], "shebang")
