    last_dot = job_name.rfind(".")
    second_last_dot = job_name.rfind(".", 0, last_dot) if last_dot > 0 else -1
    single_ext = job_name[last_dot+1:].lower()
    if second_last_dot >= 0:
        double_ext = job_name[second_last_dot+1:].lower()
        # segment between dots
        between = job_name[second_last_dot+1:last_dot]
        if double_ext in ext_map:
            return (double_ext, list(ext_map[double_ext]), "extension")
        if between == "":
            # consecutive dots -> extension is .single (unknown unless count-as added it, handled above if double_ext starts with .)
            # double_ext here is like ".go"; check again
            if double_ext in ext_map:
