    except Exception:
        text = ""
    low = text.lower()
    if s == {"MATLAB", "Objective C"}:
        # Heuristics based on probing
        objc_score = 0; mat_score = 0
        if "#import <" in text or "#include <" in text: objc_score += 3
        if "@interface" in text or "@implementation" in text or "@protocol" in text or "@end" in text: objc_score += 3
        if "//" in text: objc_score += 1
        if "/*" in text: objc_score += 0  # matlab test gave MATLAB for /* alone
        if "%" in text: mat_score += 1
        if "function" in low: mat_score += 1
        if "classdef" in low: mat_score += 2
        if objc_score > mat_score: return "Objective C"
        return "MATLAB"
    if s == {"V", "Coq", "Verilog"}:
