        if re.search(r"\bendmodule\b", text) or re.search(r"\balways\b", text) or re.search(r"\bwire\b", text) or re.search(r"\breg\b", text) or re.search(r"\bassign\b", text) or re.search(r"module\s+\w+\s*(\(|;)", text) or "`timescale" in text or re.search(r"\bposedge\b|\bnegedge\b", text):
            return "Verilog"
