# ---------------- gitignore matching ----------------
def wildmatch_to_regex(pat):
    # Convert git wildmatch pattern (without leading slash handling) to regex string matching whole path.
    i = 0; n = len(pat); out = []
    while i < n:
        c = pat[i]
        if c == "*":
            if i + 1 < n and pat[i+1] == "*":
                # ** 
                # Look at surrounding slashes handling: **/ , /** , /**/
                # Simplest: ** matches any chars including /
                out.append(".*")
                i += 2
                continue
            else:
                out.append("[^/]*"); i += 1; continue
        elif c == "?":
            out.append("[^/]"); i += 1; continue
        elif c == "[":
            # character class
            j = i + 1
            if j < n and pat[j] in ("!", "^"):
                j += 1
            if j < n and pat[j] == "]":
                j += 1
            while j < n and pat[j] != "]":
                j += 1
            if j >= n:
                out.append(re.escape("[")); i += 1; continue
            stuff = pat[i+1:j]
            if stuff.startswith("!"):
                stuff = "^" + stuff[1:]
            elif stuff.startswith("^"):
                stuff = "\\" + stuff
            # escape backslashes etc but preserve ranges
            stuff = stuff.replace("\\", "\\\\")
            out.append(f"[{stuff}]"); i = j + 1; continue
        elif c == "\\" and i + 1 < n:
            out.append(re.escape(pat[i+1])); i += 2; continue
        else:
            out.append(re.escape(c)); i += 1; continue
    return "".join(out)

class IgnorePattern:
    __slots__ = ("pattern","negate","dir_only","anchored","regex","base_rel")
    def __init__(self, raw_line, base_rel):
        line = raw_line.rstrip("\n")
        if line.endswith("\r"):
            line = line[:-1]
        # trailing spaces ignored unless escaped
        # Remove trailing spaces not preceded by backslash (simplified)
        while line.endswith(" ") and not line.endswith("\\ "):
            line = line[:-1]
        self.negate = False
        self.dir_only = False
        self.anchored = False
        self.base_rel = base_rel  # relative path of dir containing ignore file, "" for root of walk root (posix, no trailing slash)
        pat = line
        if pat.startswith("\\#") or pat.startswith("\\!"):
            pat = pat[1:]
        elif pat.startswith("!"):
            self.negate = True; pat = pat[1:]
        if pat.endswith("/"):
            self.dir_only = True; pat = pat[:-1]
            if pat == "":
                pat = ""
        # anchored if contains slash not at end (already stripped) 
        if "/" in pat:
            self.anchored = True
            if pat.startswith("/"):
                pat = pat[1:]
        self.pattern = pat
        self.regex = re.compile("^" + wildmatch_to_regex(pat) + "$") if pat else None
    def matches(self, rel_path, is_dir):
        # rel_path is path relative to walk root (posix). Convert to relative to this pattern's base.
        base = self.base_rel
        if base:
            if rel_path == base:
                rel = ""
            elif rel_path.startswith(base + "/"):
                rel = rel_path[len(base)+1:]
            else:
                return False
        else:
            rel = rel_path
        if self.pattern == "" or self.regex is None:
            return False
        if self.dir_only and not is_dir:
            return False
        if self.anchored:
            return bool(self.regex.match(rel))
        else:
            # match basename
            base_name = rel.rsplit("/", 1)[-1] if rel else ""
            return bool(self.regex.match(base_name))

def load_ignore_file(path, base_rel):
    patterns = []
    try:
        with open(path, "rb") as f:
            data = f.read()
    except Exception:
        return patterns
    text = data.decode("utf-8", "surrogateescape")
    for raw in text.split("\n"):
        # The split loses \n; IgnorePattern strips \r etc
        if raw == "" :
            continue
        # comment lines
        stripped = raw
        if stripped.startswith("#"):
            continue
        if stripped.strip() == "":
            continue
        patterns.append(IgnorePattern(raw, base_rel))
    return patterns

def is_ignored(ignore_stack, rel_path, is_dir):
    # ignore_stack is list of patterns in order of increasing depth / file order; last match wins
    ignored = False
    matched_any = False
    for pat in ignore_stack:
        if pat.matches(rel_path, is_dir):
            matched_any = True
            ignored = not pat.negate
    return ignored

def match_exclude_dir(patterns, loc_path):
    # loc_path is Location string of directory (cleaned). Patterns are exclude-dir values.
    if not patterns:
        return False
    loc = loc_path.rstrip("/")
    if loc == "":
        return False
    parts = loc.split("/")
    for pat in patterns:
        if pat == "":
            continue
        p = pat.rstrip("/")
        if p == "":
            continue
        if p.startswith("/"):
            if loc == p:
                return True
            continue
        pparts = p.split("/")
        if len(pparts) == 1:
            if parts and parts[-1] == pparts[0]:
                return True
        else:
            if len(pparts) <= len(parts) and parts[-len(pparts):] == pparts:
                return True
    return False

