# ---------------- Summary ----------------
class LangSummary:
    __slots__ = ("Name","Bytes","CodeBytes","Lines","Code","Comment","Blank","Complexity","Count","WeightedComplexity","Files","LineLength","ULOC","_line_lengths","_uloc_set")
    def __init__(self, name):
