    # Our formatters will take `results` as separate arg where needed. For summary Files needed by tabular byfile etc, opts.by_file controls.
    return summaries

def sort_summaries(summaries, sort_by):
    by = (sort_by or "files").lower()
    # aliases for MCP are handled before calling by mapping sort name
