    elif by == "lines":
        summaries.sort(key=lambda s: (-s.Lines, s.Name))
    elif by in ("blanks", "blank"):
        summaries.sort(key=lambda s: (-s.Blank, s.Name))
    elif by == "code":
        summaries.sort(key=lambda s: (-s.Code, s.Name))
    elif by in ("comments", "comment"):
        summaries.sort(key=lambda s: (-s.Comment, s.Name))
    elif by == "complexity":
        summaries.sort(key=lambda s: (-s.Complexity, s.Name))
    elif by == "bytes":
        summaries.sort(key=lambda s: (-s.Bytes, s.Name))
    else:  # files and unknown
        summaries.sort(key=lambda s: (-s.Count, s.Name))
    return summaries

