def go_json_escape_str(s):
    if not isinstance(s, str):
        s = str(s)
    # Convert surrogateescape to bytes then decode utf8 replace to mimic Go invalid utf8 replacement
    try:
        b = s.encode("utf-8", "surrogateescape")
    except Exception:
        b = s.encode("utf-8", "replace")
    s2 = b.decode("utf-8", "replace")
    out = ['"']
    for ch in s2:
        o = ord(ch)
        if ch == '"': out.append('\\"')
        elif ch == '\\': out.append('\\\\')
        elif ch == '\n': out.append('\\n')
        elif ch == '\r': out.append('\\r')
        elif ch == '\t': out.append('\\t')
        elif ch == '<': out.append('\\u003c')
        elif ch == '>': out.append('\\u003e')
        elif ch == '&': out.append('\\u0026')
        elif o < 0x20:
            out.append(f'\\u{o:04x}')
        elif o in (0x2028, 0x2029):
            out.append(f'\\u{o:04x}')
        else:
            out.append(ch)
    out.append('"')
    return ''.join(out)

def go_json_float(v):
    if math.isnan(v) or math.isinf(v):
        raise ValueError("json: unsupported value: " + str(v))
    if v == 0:
        return "-0" if math.copysign(1.0, v) < 0 else "0"
    av = abs(v)
    if 1e-6 <= av < 1e21:
        s = repr(v)
        if 'e' in s or 'E' in s:
            # convert to fixed
            from decimal import Decimal
            s = format(Decimal(s), 'f')
        if s.endswith('.0'):
            s = s[:-2]
        return s
    else:
        s = repr(v)
        if 'e' not in s and 'E' not in s:
            # format in exponent then clean trailing zeros
            s = format(v, '.15e')
            # remove trailing zeros in mantissa
            if '.' in s:
                mant, exp = s.split('e')
                mant = mant.rstrip('0').rstrip('.')
                s = mant + 'e' + exp
        return s

def go_json_dumps(obj):
    if obj is None:
        return "null"
    if obj is True:
        return "true"
    if obj is False:
        return "false"
    if isinstance(obj, str):
        return go_json_escape_str(obj)
    if isinstance(obj, int):
        return str(obj)
    if isinstance(obj, float):
        return go_json_float(obj)
    if isinstance(obj, (list, tuple)):
        return "[" + ",".join(go_json_dumps(x) for x in obj) + "]"
    if isinstance(obj, dict):
        return "{" + ",".join(go_json_escape_str(str(k)) + ":" + go_json_dumps(v) for k, v in obj.items()) + "}"
    raise TypeError(f"unsupported json type {type(obj)}")

