def truncate_left_ellipsis(s, maxlen):
    if len(s) > maxlen:
        return s[:maxlen-1] + "…" if maxlen >= 1 else ""
    return s

def truncate_right_tilde(s, maxlen):
    if len(s) > maxlen:
        if maxlen <= 1: return "~"[:maxlen]
        return "~" + s[-(maxlen-1):]
    return s

def row_from_endpoints(left_text, values, endpoints, total_len):
    # values are strings right-aligned ending at endpoints indexes.
    # If a value is too long for its segment, we fall back to simply joining with spaces (expansion)
    # First check fits
    prev_end = -1
    fits = True
    for v, ep in zip(values, endpoints):
        start = ep - len(v) + 1
        # need at least one space after left/prev if previous is left text for first or previous endpoint
        min_start = len(left_text) if prev_end == -1 else prev_end + 1
        if start <= min_start and not (prev_end==-1 and start==len(left_text)):
            # Actually need at least one space separation unless left text exactly fills? We'll permit start==min_start? Original expands in this case.
            # Use fits only if start > min_start or (start==min_start and False)
            if start <= min_start:
                fits = False; break
        prev_end = ep
    if not fits:
        # sequential fallback: left padded to first endpoint segment via values joined
        # Build by padding each value to segment width derived from endpoints (first segment width endpoint+1 for combined left+first)
        out = left_text
        # place first value right aligned to endpoints[0] relative to current length
        for idx, (v, ep) in enumerate(zip(values, endpoints)):
            target_len = ep + 1
            if len(out) < target_len - len(v):
                out += " " * (target_len - len(v) - len(out))
            else:
                out += " "
            out += v
        return out
    chars = [" "] * total_len
    for i,ch in enumerate(left_text[:total_len]):
        chars[i] = ch
    for v, ep in zip(values, endpoints):
        start = ep - len(v) + 1
        for j,ch in enumerate(v):
            if 0 <= start+j < total_len:
                chars[start+j] = ch
            elif start+j >= total_len:
                chars.append(ch)
    return "".join(chars).rstrip()

def partial_row(left_text, values, endpoints):
    # Row truncated after last endpoint (no trailing)
    if not endpoints:
        return left_text
    total_len = endpoints[-1] + 1
    return row_from_endpoints(left_text, values, endpoints, total_len)

def percent_str(num, den):
    if den == 0:
        # Go float division 0/0 NaN, x/0 Inf; original formatting likely %.1f%% -> NaN% / +Inf% ? We'll use python mimic later tests
        if num == 0:
            return "NaN%"
        return "+Inf%" if num > 0 else "-Inf%"
    return f"{(num/den*100):.1f}%"

