    return lines

def go_pow(x, y):
    # Emulate Go math.Pow sufficiently
    try:
        if y == 0:
            return 1.0
        if x == 0:
            return 0.0 if y > 0 else float("inf")
        if math.isinf(x):
            # Go Pow(-Inf, y): sign depends on y being odd integer
            if y < 0:
                return 0.0
            if float(y).is_integer() and int(y) % 2 == 1 and x < 0:
                return float("-inf")
            return float("inf")
        if x < 0 and not float(y).is_integer():
            return float("nan")
        return math.pow(x, y)
    except OverflowError:
        return float("inf") if not (x < 0 and float(y).is_integer() and int(y)%2==1) else float("-inf")
    except Exception:
        return float("nan")

def size_lines(opts, totals):
    if opts.no_size:
        return []
    unit_raw = (opts.size_unit or "si").lower()
    known = {"si","binary","mixed","xkcd-kb","xkcd-kelly","xkcd-imaginary","xkcd-intel","xkcd-drive","xkcd-bakers"}
    unit = unit_raw if unit_raw in known else "si"
    desc = None
    mb_str = None
    b = totals["Bytes"]
    def fmt_mb(divisor):
        return f"{b/divisor:.3f}"
    if unit == "si":
        mb_str = fmt_mb(1000*1000)
    elif unit == "binary":
        mb_str = fmt_mb(1024*1024)
    elif unit == "mixed":
        mb_str = fmt_mb(1000*1024)
    elif unit == "xkcd-kb":
        desc = "1000 bytes during leap years, 1024 otherwise"
        year = datetime.datetime.now().year
        is_leap = (year % 4 == 0 and (year % 100 != 0 or year % 400 == 0))
        mb_str = fmt_mb(1000*1000) if is_leap else "0.000"
    elif unit == "xkcd-kelly":
        desc = "compromise between 1000 and 1024 bytes"
        mb_str = fmt_mb(1012*1012)
    elif unit == "xkcd-imaginary":
        desc = "used in quantum computing"
        mb_str = "¯\\_(ツ)_/¯"
    elif unit == "xkcd-intel":
        desc = "calculated on pentium F.P.U."
        mb_str = fmt_mb(1023.937528*1023.937528)
    elif unit == "xkcd-drive":
        desc = "shrinks by 4 bytes every year for marketing reasons"
        year = datetime.datetime.now().year
        u = 8960 - 4*year
        mb_str = fmt_mb(u*u) if u != 0 else "0.000"
    elif unit == "xkcd-bakers":
        desc = "9 bits to the byte since you're such a good customer"
        mb_str = fmt_mb(1152*1152)
    lines = []
    if desc:
        lines.append(desc)
    lines.append(f"Processed {b} bytes, {mb_str} megabytes ({unit.upper()})")
    return lines

