    lines.append(f"Estimated Cost to Develop ({label}) {sym}{format_int_comma(go_int_from_float(cost))}")
    # schedule formatting with commas, Inf -> ∞, NaN -> NaN
    if isinstance(schedule,float) and math.isinf(schedule):
        sched_str = "∞" if schedule>0 else "-∞"
