def go_pow(x, y):
    # Emulate Go math.Pow sufficiently
    try:
        if y == 0:
            return 1.0
        if x == 0:
            return 0.0 if y > 0 else float("inf")
        if math.isinf(x):
            # Go Pow(-Inf, y): sign depends on y being odd integer
            if y < 0:
                return 0.0
            if float(y).is_integer() and int(y) % 2 == 1 and x < 0:
                return float("-inf")
            return float("inf")
        if x < 0 and not float(y).is_integer():
            return float("nan")
        return math.pow(x, y)
    except OverflowError:
        return float("inf") if not (x < 0 and float(y).is_integer() and int(y)%2==1) else float("-inf")
    except Exception:
        return float("nan")

