def go_json_dumps_pretty(obj, indent=2, level=0):
    pad = " " * (indent * level)
    pad2 = " " * (indent * (level+1))
    if isinstance(obj, dict):
        if not obj: return "{}"
        items = []
        for k,v in obj.items():
            items.append(f"{pad2}{go_json_escape_str(str(k))}: {go_json_dumps_pretty(v, indent, level+1)}")
        return "{\n" + ",\n".join(items) + f"\n{pad}}}"
    if isinstance(obj, (list,tuple)):
        if not obj: return "[]"
        items = [f"{pad2}{go_json_dumps_pretty(v, indent, level+1)}" for v in obj]
        return "[\n" + ",\n".join(items) + f"\n{pad}]"
    return go_json_dumps(obj)

def sort_files_for_mcp(files, sort_arg):
    by = (sort_arg or "files").lower()
    if by == "name":
        return sorted(files, key=lambda f: f.Location)
    if by == "lines":
        return sorted(files, key=lambda f: (-f.Lines, f.Location))
    if by in ("blank","blanks"):
        return sorted(files, key=lambda f: (-f.Blank, f.Location))
    if by == "code":
        return sorted(files, key=lambda f: (-f.Code, f.Location))
    if by in ("comment","comments"):
        return sorted(files, key=lambda f: (-f.Comment, f.Location))
    if by == "complexity":
        return sorted(files, key=lambda f: (-f.Complexity, f.Location))
    if by == "bytes":
        return sorted(files, key=lambda f: (-f.Bytes, f.Location))
    # files/default -> lines descending as observed for MCP file lists
    return sorted(files, key=lambda f: (-f.Lines, f.Location))

