        from completiondata import SCRIPTS, HELP as COMP_HELP, USAGE as COMP_USAGE
    except Exception:
        try:
            from .completiondata import SCRIPTS, HELP as COMP_HELP, USAGE as COMP_USAGE
        except Exception:
            return {}, {}, {}
    return SCRIPTS, COMP_HELP, COMP_USAGE

def find_completion_invocation(argv):
    # Return index of 'completion' token if it is first non-flag positional before --, else None.
    # Need skip flags and their values approximately like Cobra's Find (it strips flags).
    i = 0
    # Cobra Find uses flags parsing knowledge to skip flag values when searching for subcommand.
    # Implement: iterate tokens; if token is '--' stop; if token starts '-' handle like parse (bool flags don't consume, non-bool may consume next or have =)
    while i < len(argv):
        a = argv[i]
        if a == "--":
            return None
        if a.startswith("--"):
            body = a[2:]
            if "=" in body:
                i += 1; continue
            name = body
            defn = FLAG_BY_NAME.get(name)
            if defn and defn[2] != "bool":
                i += 2; continue
            i += 1; continue
        if a.startswith("-") and a != "-":
            # shorthand cluster: if any non-bool in cluster, it may consume rest or next
            cluster = a[1:]
            consumed_next = False
            pos = 0
            while pos < len(cluster):
                d = FLAG_BY_SHORT.get(cluster[pos])
                if d is None:
                    break
                if d[2] == "bool":
                    if pos+1 < len(cluster) and cluster[pos+1] == "=":
                        pos = len(cluster); break
                    pos += 1; continue
                else:
                    if pos+1 < len(cluster):
                        pos = len(cluster)
                    else:
                        consumed_next = True; pos = len(cluster)
                    break
            i += 2 if consumed_next else 1
            continue
        # first positional
        if a == "completion":
            return i
        return None
    return None

def run_completion_command(argv, completion_idx):
    scripts, comp_help, comp_usage = load_completion_data()
    # Args for completion command are argv with 'completion' token removed? Cobra parses root persistent flags anywhere interspersed.
    # Determine shell subcommand: first positional after completion_idx skipping flags (similar find)
    rest = argv[:completion_idx] + argv[completion_idx+1:]
    # Now parse flags using an augmented flag set: root flags + --no-descriptions (bool, only meaningful on shell subcommands; on parent, Cobra would say unknown flag if used before subcommand? Parent has only help + global; --no-descriptions is a local flag of shell subcommands, but Cobra parses it after subcommand determined)
    # Find shell token in rest positionals using flag-skipping on rest (root flags only knowledge plus no-descriptions bool)
    shell = None; shell_idx_in_rest = None
    i = 0
    while i < len(rest):
        a = rest[i]
        if a == "--":
            i += 1; break
        if a.startswith("--"):
            body = a[2:].split("=",1)[0]
            if "=" in a:
                i += 1; continue
            d = FLAG_BY_NAME.get(body)
            if body == "no-descriptions":
                i += 1; continue
            if d and d[2] != "bool":
                i += 2; continue
            i += 1; continue
        if a.startswith("-") and a != "-":
            # simplistic skip
            i += 1; continue
        shell = a; shell_idx_in_rest = i; break
    shells = ("bash","fish","zsh","powershell")
    if shell is None or shell not in shells:
        # Parent completion command: parse root flags in rest for errors/help
        # Unknown positional shell names result in help exit 0 in original, but flags parse errors? Test approximated.
        try:
            opts, pos = parse_flags(rest)
        except FlagError as e:
            # Usage for parent completion command
            sys.stderr.write(f"Error: {e}\n")
            usage = comp_usage.get("", USAGE_TEXT)
            sys.stderr.write(usage)
            if not usage.endswith("\n\n"):
                sys.stderr.write("\n")
            return 1
        # help flag or no/invalid shell: print parent help
        sys.stdout.write(comp_help.get("", ""))
        return 0
    # Shell subcommand: rest without shell token = flags to parse (root + no-descriptions)
    shell_args = rest[:shell_idx_in_rest] + rest[shell_idx_in_rest+1:]
    # Check for help or extra positional / unknown flags by parsing with no-descriptions support
    # Implement manual scan: use parse_flags with allow_completion_flags on a modified argv where --no-descriptions present.
    # parse_flags knows no-descriptions pseudo if allow flag passed.
    try:
        opts, pos = parse_flags(shell_args, allow_completion_flags=True)
    except FlagError as e:
        sys.stderr.write(f"Error: {e}\n")
        usage = comp_usage.get(shell, USAGE_TEXT)
        sys.stderr.write(usage)
        if not usage.endswith("\n\n"):
            sys.stderr.write("\n")
        return 1
    if getattr(opts, "help", False):
        sys.stdout.write(comp_help.get(shell, ""))
        return 0
    if pos:
        # unknown command "extra" for "scc completion bash"
        sys.stderr.write(f'Error: unknown command "{pos[0]}" for "scc completion {shell}"\n')
        usage = comp_usage.get(shell, USAGE_TEXT)
        sys.stderr.write(usage)
        if not usage.endswith("\n\n"):
            sys.stderr.write("\n")
        return 1
    nodesc = getattr(opts, "no_descriptions", False)
    key = shell + ("_nodesc" if nodesc else "")
    script = scripts.get(key) or scripts.get(shell) or ""
    sys.stdout.write(script)
    return 0

def run_complete(argv, no_desc=False):
    # argv after __complete/__completeNoDesc are words; last word is toComplete (may be '')
    # Output: completions lines (value[\t description]), then :directive, then blank line. To stderr: Completion ended...
    words = argv
    to_complete = words[-1] if words else ""
    prior = words[:-1] if words else []
    # Detect if prior parsing had unknown flag (Cobra prints debug to stderr and directive default)
    # Simplified behavior:
    directive = 0
    directive_name = "ShellCompDirectiveDefault"
    completions = []
    debug_err = None
    # If prior first positional is completion and toComplete is not flag
    # Remove any leading flags handling roughly
    # Check for unknown flag in prior tokens
    for tok in prior:
        if tok.startswith("--"):
            name = tok[2:].split("=",1)[0]
            if name not in FLAG_BY_NAME and name != "no-descriptions":
                debug_err = f"[Debug] [Error] Error while parsing flags from args {prior}: unknown flag: --{name}"
                # Go: args formatting uses Go slice %v: [--unknown] ; our prior list repr differs - construct
                go_args = '[' + ' '.join(prior) + ']'
                debug_err = f"[Debug] [Error] Error while parsing flags from args {go_args}: unknown flag: --{name}"
                break
    if debug_err:
        out = ":0\n\n"
        sys.stdout.write(out)
        sys.stderr.write(debug_err + "\n")
        sys.stderr.write(f"Completion ended with directive: {directive_name}\n")
        return 0
    # Completion subcommand context
    # Find positional tokens in prior (very rough)
    positionals = [t for t in prior if not t.startswith("-")]
    if positionals and positionals[0] == "completion" and not to_complete.startswith("-"):
        shells = [("bash","Generate the autocompletion script for bash"),("fish","Generate the autocompletion script for fish"),("powershell","Generate the autocompletion script for powershell"),("zsh","Generate the autocompletion script for zsh")]
        for name, desc in shells:
            if name.startswith(to_complete):
                completions.append((name, desc))
        directive = 4; directive_name = "ShellCompDirectiveNoFileComp"
    elif to_complete.startswith("-"):
        # Determine if prior is completion shell subcommand: include its flags? Simplify to root flags plus no-descriptions if shell context
        in_shell = len(positionals) >= 2 and positionals[0] == "completion" and positionals[1] in ("bash","fish","zsh","powershell")
        flag_items = []
        for name, short, typ, default, usage in FLAG_DEFS:
            flag_items.append((f"--{name}", usage))
            if to_complete == "-" and short:
                flag_items.append((f"-{short}", usage))
        if in_shell:
            # Local flags first in Cobra? Commands' local flags may appear along globals sorted? Simplistic append
            flag_items.append(("--no-descriptions", "disable completion descriptions"))
            flag_items = sorted(flag_items, key=lambda x: x[0].lstrip("-"))
        for val, desc in flag_items:
            if val.startswith(to_complete):
                completions.append((val, desc))
        # Cobra sorts by flag name - FLAG_DEFS is already alphabetical by long name (check ordering in help). Our list is in help order.
        directive = 4; directive_name = "ShellCompDirectiveNoFileComp"
    else:
        # If prior token is a flag expecting value, directive default no completions (file completion)
        directive = 0; directive_name = "ShellCompDirectiveDefault"
    for val, desc in completions:
        if no_desc:
            sys.stdout.write(f"{val}\n")
        else:
            sys.stdout.write(f"{val}\t{desc}\n")
    sys.stdout.write(f":{directive}\n\n")
    sys.stderr.write(f"Completion ended with directive: {directive_name}\n")
    return 0

# ---------------- Main ----------------
def main(argv):
    # __complete handling if first arg is exactly that
    if argv and argv[0] in ("__complete", "__completeNoDesc"):
        return run_complete(argv[1:], no_desc=(argv[0] == "__completeNoDesc"))
    # Completion subcommand detection
    cidx = find_completion_invocation(argv)
    if cidx is not None:
        return run_completion_command(argv, cidx)
    try:
        opts, inputs = parse_flags(argv)
    except FlagError as e:
        print_flag_error(str(e), USAGE_TEXT)
        return 1
    Logger.verbose = opts.verbose
    Logger.debug = opts.debug
    Logger.trace = opts.trace
    if opts.help:
        sys.stdout.write(HELP_TEXT)
        return 0
    if opts.version:
        sys.stdout.write(f"scc version {VERSION}\n")
        return 0
    if opts.languages:
        sys.stdout.write(LANGUAGES_TEXT if LANGUAGES_TEXT.endswith("\n") else LANGUAGES_TEXT + "\n")
        return 0
    if opts.mcp:
        return run_mcp()
    # Defaults
    if not inputs:
        inputs = ["."]
    # Validate inputs (after debug header? Original debug header prints in Process before validation? In earlier debug run with /tmp/trace_one/a.py nonexistent file, debug header printed then file not read line. So print debug header before validation.)
    print_debug_header(opts)
    for inp in inputs:
        try:
            os.stat(inp)
        except OSError:
            sys.stdout.write(f"file or directory could not be read: {inp}\n")
            return 1
    try:
        process(opts, inputs)
    except CocomoPanic:
        # Emulate Go panic to stderr exit 2 (stack trace inexact)
        sys.stderr.write("panic: runtime error: index out of range [1] with length 0\n\n")
        sys.stderr.write("goroutine 1 [running]:\n")
        sys.stderr.write("github.com/boyter/scc/v3/processor.EstimateEffort(...)\n")
        return 2
    return 0

if __name__ == "__main__":
    try:
        code = main(sys.argv[1:])
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        code = 0
    sys.exit(code)
