words=["type","fragment","query","mutation","subscription","schema","interface","union","enum","input","extend","scalar","directive","implements","cond","given","otherwise","orelse","andalso","foreach","forall","doseq","dotimes","loop","recur","let","defn","def","fn","lambda","call","invoke","perform","evaluate","inspect","require","module","class","object","trait","struct","interface","package","namespace","using","include","import","from","select","where","join","group","order","having","limit"]
for w in words:
