    items.append((f"W:{w}(",f"{w}(x\n"))
    items.append((f"LP:{w}",f"({w} x)\n"))
for tok in [".","?.","@","$","::","->","=>","&","|","&&","||","?",":",";",",","#","*","+","-","=","==","!=","<",">","<=",">=","+=","|=",":=","..","...","->>","<-","<|","|>","$>","<*>","<$>","=>>"]:
