    items.append((f"S:{tok} ",f"{tok} x\n"))
    items.append((f"S: {tok} ",f"x {tok} x\n"))
out={}
for idx,lang in enumerate(langs):
    d="/tmp/lang_probe_dir"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
