from langdata import FEATURES
# --- Fix multi pairs from comment probes with correct literal parsing ---
def parse_pair(cand):
    m=re.match(r"^('(?:[^'\\]|\\.)*'|\"(?:[^\"\\]|\\.)*\")\|(.*)$",cand,re.S)
    if not m: return None
    try:
        return (ast.literal_eval(m.group(1)), ast.literal_eval(m.group(2)))
    except Exception:
        return None
alltests={}
for fn in ["/tmp/lang_comments.json","/tmp/lang_comments2.json"]:
    for e in json.load(open(fn)):
        alltests.setdefault(e["language"],[]).extend(e["tests"])
# extra pairs file is dict lang->tests
extra=json.load(open("/tmp/lang_pairs_extra.json"))
for lang,tests in extra.items():
    alltests.setdefault(lang,[]).extend(tests)
more=json.load(open("/tmp/lang_more.json"))
for lang,tests in alltests.items():
    pair_ok=[]
    for kind,cand,res in tests:
        if kind in ("multi","multi_endstart") and res and res[2]==1 and res[3]==3:
            pair=parse_pair(cand)
            if pair and pair not in pair_ok: pair_ok.append(pair)
    pair_sel=[]
    for pair in sorted(pair_ok,key=lambda p:(len(p[0])+len(p[1]),len(p[0]),p)):
        s,e=pair
        if any(s.startswith(ks) and (e.endswith(ke) or ke in e) for ks,ke in pair_sel):
            continue
        pair_sel.append(pair)
    # Preserve nested flags from existing FEATURES if pair existed; recompute nested using more by finding pair in old multi list index only approximates.
    old_multi=FEATURES.get(lang,{}).get("multi",[])
    new_multi=[]
    for s,e in pair_sel:
        nested=False
        for old in old_multi:
            if old[0]==s and old[1]==e:
                nested=bool(old[2]) if len(old)>2 else False
        new_multi.append([s,e,nested])
    if lang in FEATURES:
        # Only replace multi if recomputed differs and not docstring/smalltalk/algol special handled below
        FEATURES[lang]["multi"]=new_multi
# Re-apply special cases
FEATURES["Algol 68"]["multi"]=[["#","#",False]]
FEATURES["Smalltalk"]["multi"]=[['"','"',False]]
for lang in ["Python","Mojo","PRQL","Snakemake","GraphQL"]:
    if lang in FEATURES:
        FEATURES[lang]["multi"]=[p for p in FEATURES[lang]["multi"] if p[0] not in ('"""',"'''",'r"""')]
        FEATURES[lang]["docstring"]=True
# Nested recompute for newly added pairs is unknown; keep False except known nested pairs languages will retain if old.
# For Lean pair, nested in Lean 4 block comments nest - test later and patch if needed.

# --- Merge complexity probe3 ---
cx3=json.load(open("/tmp/lang_complexity3.json"))
for lang,res in cx3.items():
    if lang not in FEATURES: continue
    existing=list(FEATURES[lang].get("complexity",[]))
    inferred=[]
    # Word items
    for k,v in res.items():
        if not v: continue
        if k.startswith("W:"):
            tok=k[2:]
            inferred.append(tok)
        elif k.startswith("LP:"):
            w=k[3:]
            inferred.append(f"({w} ")
    # Symbol items group by tok base
    # Keys are S:{tok}, S:{tok}␣ (key includes trailing space in our generation "S:{tok} "), S:␣{tok}␣ ("S: {tok} ")
    syms={}
    for k,v in res.items():
        if not v or not k.startswith("S:"): continue
        body=k[2:]
        if body.startswith(" "):
